"""Order fulfillment JSON CLI entry point."""

from __future__ import annotations

import argparse
import json
import sys
import time
import uuid

from . import OrderError, OrderService


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--db", required=True, help="Path to SQLite database")
    parser.add_argument("command", choices=["stock", "create", "pay", "cancel", "ship", "get"], help="Command to execute")
    args = parser.parse_args()

    # Read input
    input_obj = {}
    if args.command not in ("init", "recover", "list"):  # just following pattern, though init/recover/list aren't for orders
        try:
            line = sys.stdin.readline()
            if line.strip():
                input_obj = json.loads(line)
        except json.JSONDecodeError:
            print_error("INVALID_INPUT", "Invalid JSON input")
            sys.exit(2)

    if not isinstance(input_obj, dict):
        print_error("INVALID_INPUT", "Input must be a JSON object")
        sys.exit(2)

    # Create service
    try:
        service = OrderService(
            args.db,
            clock=time.time,
            id_factory=lambda: uuid.uuid4().hex
        )
    except OrderError as e:
        print_error(e.code, e.message, e.details)
        sys.exit(2 if e.code in ("INVALID_INPUT", "INVALID_DEPENDENCY", "SCHEMA_MISMATCH") else 3)
    except Exception as e:
        print_error("STORAGE_ERROR", str(e))
        sys.exit(3)

    # Execute command
    try:
        if args.command == "stock":
            sku = input_obj.get("sku")
            quantity = input_obj.get("quantity")
            extra_keys = set(input_obj.keys()) - {"sku", "quantity"}
            if extra_keys:
                raise OrderError("INVALID_INPUT", f"Unknown keys: {sorted(extra_keys)}")
            result = service.set_stock(sku, quantity)
        elif args.command == "create":
            idempotency_key = input_obj.get("idempotency_key")
            items = input_obj.get("items")
            extra_keys = set(input_obj.keys()) - {"idempotency_key", "items"}
            if extra_keys:
                raise OrderError("INVALID_INPUT", f"Unknown keys: {sorted(extra_keys)}")
            result = service.create_order(idempotency_key, items)
        elif args.command == "pay":
            order_id = input_obj.get("order_id")
            payment_id = input_obj.get("payment_id")
            amount_cents = input_obj.get("amount_cents")
            extra_keys = set(input_obj.keys()) - {"order_id", "payment_id", "amount_cents"}
            if extra_keys:
                raise OrderError("INVALID_INPUT", f"Unknown keys: {sorted(extra_keys)}")
            result = service.pay_order(order_id, payment_id, amount_cents)
        elif args.command == "cancel":
            order_id = input_obj.get("order_id")
            extra_keys = set(input_obj.keys()) - {"order_id"}
            if extra_keys:
                raise OrderError("INVALID_INPUT", f"Unknown keys: {sorted(extra_keys)}")
            result = service.cancel_order(order_id)
        elif args.command == "ship":
            order_id = input_obj.get("order_id")
            extra_keys = set(input_obj.keys()) - {"order_id"}
            if extra_keys:
                raise OrderError("INVALID_INPUT", f"Unknown keys: {sorted(extra_keys)}")
            result = service.ship_order(order_id)
        elif args.command == "get":
            order_id = input_obj.get("order_id")
            extra_keys = set(input_obj.keys()) - {"order_id"}
            if extra_keys:
                raise OrderError("INVALID_INPUT", f"Unknown keys: {sorted(extra_keys)}")
            result = service.get_order(order_id)
        else:
            raise OrderError("INVALID_INPUT", f"Unknown command: {args.command}")
    except OrderError as e:
        print_error(e.code, e.message, e.details)
        sys.exit(2)
    except Exception as e:
        print_error("STORAGE_ERROR", str(e))
        sys.exit(3)

    # Print success
    print(json.dumps({"ok": True, "result": result}, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False))


def print_error(code: str, message: str, details: dict | None = None) -> None:
    error_obj = {"code": code, "message": message, "details": details or {}}
    print(json.dumps({"ok": False, "error": error_obj}, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False))


if __name__ == "__main__":
    main()

