"""Delivery spool candidate API implementation."""

from __future__ import annotations

import dataclasses
import fcntl
import json
import os
import secrets
import time
from typing import Any, Dict, Optional, List


@dataclasses.dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0


class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        self.code = code
        self.message = message
        self.details = details or {}
        super().__init__(message)

    def __str__(self) -> str:
        return self.message


class Spool:
    """Filesystem-backed lease spool."""

    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        self.root = root
        self.clock = clock
        self.limits = limits
        self.lock_timeout = lock_timeout
        self.failpoint = failpoint

        # Validate limits
        self._validate_limits(limits)

        # Validate dependencies
        try:
            t = clock()
            if not isinstance(t, (int, float)) or not (float("-inf") < t < float("inf")):
                raise SpoolError("INVALID_DEPENDENCY", "clock() must return a finite number")
        except Exception as e:
            if isinstance(e, SpoolError):
                raise
            raise SpoolError("INVALID_DEPENDENCY", f"clock() failed: {e}") from e

        if not isinstance(lock_timeout, (int, float)) or lock_timeout < 0 or not (float("-inf") < lock_timeout < float("inf")):
            raise SpoolError("INVALID_INPUT", "lock_timeout must be a finite non-negative number")

    def _validate_limits(self, limits: Limits):
        if not isinstance(limits, Limits):
            raise SpoolError("INVALID_INPUT", "limits must be a Limits instance")
        # Validate each field
        for field, (min_val, is_int) in [
            ("max_messages", (1, True)),
            ("max_payload_bytes", (1, True)),
            ("max_attempts", (1, True)),
            ("lease_seconds", (0, False)),
            ("retry_delay", (0, False)),
        ]:
            val = getattr(limits, field)
            if is_int:
                if isinstance(val, bool) or not isinstance(val, int):
                    raise SpoolError("INVALID_INPUT", f"{field} must be an integer")
            else:
                if not isinstance(val, (int, float)):
                    raise SpoolError("INVALID_INPUT", f"{field} must be a number")
            if val < min_val or not (float("-inf") < val < float("inf")):
                raise SpoolError("INVALID_INPUT", f"{field} must be a finite number >= {min_val}")
        if limits.lease_seconds <= 0:
            raise SpoolError("INVALID_INPUT", "lease_seconds must be > 0")

    def _state_path(self):
        return os.path.join(self.root, "state.json")

    def _lock_path(self):
        return os.path.join(self.root, "state.lock")

    def _acquire_lock(self, exclusive: bool = True):
        os.makedirs(self.root, exist_ok=True)
        lock_fd = os.open(self._lock_path(), os.O_CREAT | os.O_RDWR)
        lock_op = fcntl.LOCK_EX if exclusive else fcntl.LOCK_SH
        deadline = time.time() + self.lock_timeout
        while True:
            try:
                fcntl.flock(lock_fd, lock_op | fcntl.LOCK_NB)
                return lock_fd
            except BlockingIOError:
                if time.time() >= deadline:
                    os.close(lock_fd)
                    raise SpoolError("LOCK_TIMEOUT", "Failed to acquire lock within timeout")
                time.sleep(0.01)

    def _release_lock(self, lock_fd):
        try:
            fcntl.flock(lock_fd, fcntl.LOCK_UN)
        finally:
            os.close(lock_fd)

    def _read_state(self, lock_fd):
        state_path = self._state_path()
        if not os.path.exists(state_path):
            return None

        with open(state_path, "r", encoding="utf-8") as f:
            try:
                state = json.load(f)
            except json.JSONDecodeError:
                raise SpoolError("CORRUPT_STATE", "State file contains invalid JSON")

        # Validate state
        self._validate_state(state)
        return state

    def _validate_state(self, state):
        if not isinstance(state, dict):
            raise SpoolError("CORRUPT_STATE", "State must be a dict")
        if "schema_version" not in state:
            raise SpoolError("SCHEMA_MISMATCH", "Missing schema_version")
        if state["schema_version"] != 1:
            raise SpoolError("SCHEMA_MISMATCH", f"Unknown schema_version: {state['schema_version']}")
        if "next_sequence" not in state or not isinstance(state["next_sequence"], int) or state["next_sequence"] < 1:
            raise SpoolError("CORRUPT_STATE", "Invalid next_sequence")
        if "messages" not in state or not isinstance(state["messages"], dict):
            raise SpoolError("CORRUPT_STATE", "Invalid messages")

        valid_statuses = {"pending", "leased", "acked", "dead"}
        for msg_id, msg in state["messages"].items():
            if not isinstance(msg, dict):
                raise SpoolError("CORRUPT_STATE", f"Invalid message {msg_id}")
            for key in ("message_id", "payload", "status", "available_at", "sequence", "attempts", "last_error"):
                if key not in msg:
                    raise SpoolError("CORRUPT_STATE", f"Message {msg_id} missing {key}")
            if msg["status"] not in valid_statuses:
                raise SpoolError("CORRUPT_STATE", f"Message {msg_id} has invalid status {msg['status']}")
            if msg["status"] == "leased":
                for key in ("lease_token", "worker_id", "expires_at"):
                    if key not in msg:
                        raise SpoolError("CORRUPT_STATE", f"Leased message {msg_id} missing {key}")

    def _write_state(self, state, lock_fd):
        # Call failpoints if provided
        if self.failpoint is not None:
            self.failpoint("before_replace")

        # Write to temporary file
        import os
        import tempfile
        tmp_path = os.path.join(self.root, f".state.{os.getpid()}.{secrets.token_hex(8)}.tmp")
        try:
            with open(tmp_path, "w", encoding="utf-8") as f:
                json.dump(
                    state,
                    f,
                    sort_keys=True,
                    separators=(",", ":"),
                    ensure_ascii=False,
                    allow_nan=False
                )
                f.write("\n")
                f.flush()
                os.fsync(f.fileno())

            # Atomic replace
            os.replace(tmp_path, self._state_path())

            # Call after_replace failpoint
            if self.failpoint is not None:
                self.failpoint("after_replace")

            # Fsync directory
            dir_fd = os.open(self.root, os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
        finally:
            # Clean up temporary file if it still exists
            if os.path.exists(tmp_path):
                try:
                    os.unlink(tmp_path)
                except:
                    pass

    def _message_public(self, msg: dict, include_lease_token: bool = False) -> dict:
        public = {
            "message_id": msg["message_id"],
            "payload": msg["payload"],
            "status": msg["status"],
            "available_at": msg["available_at"],
            "sequence": msg["sequence"],
            "attempts": msg["attempts"],
            "last_error": msg["last_error"],
        }
        if include_lease_token and "lease_token" in msg:
            public["lease_token"] = msg["lease_token"]
        return public

    def initialize(self) -> dict:
        lock_fd = self._acquire_lock(exclusive=True)
        try:
            state_path = self._state_path()
            if os.path.exists(state_path):
                # Check if it's already initialized
                try:
                    self._read_state(lock_fd)
                    raise SpoolError("ALREADY_INITIALIZED", "Spool already initialized")
                except SpoolError as e:
                    if e.code not in ("CORRUPT_STATE", "SCHEMA_MISMATCH"):
                        raise
                    # If corrupted, don't overwrite - fail closed
                    raise

            if self.failpoint is not None:
                self.failpoint("after_lock")

            # Initialize new state
            state = {
                "schema_version": 1,
                "next_sequence": 1,
                "messages": {},
            }
            self._write_state(state, lock_fd)
            return {"ok": True}
        except SpoolError:
            raise
        except Exception as e:
            raise SpoolError("INTERNAL_ERROR", f"Failed to initialize: {e}") from e
        finally:
            self._release_lock(lock_fd)

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        # Validate inputs first
        if not isinstance(message_id, str) or not message_id.strip():
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty non-whitespace string")

        # Validate payload and its canonical length
        try:
            payload_canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
        except (TypeError, ValueError):
            raise SpoolError("INVALID_INPUT", "payload must be JSON serializable without nan/inf")
        payload_bytes = payload_canonical.encode("utf-8")
        if len(payload_bytes) > self.limits.max_payload_bytes:
            raise SpoolError("INVALID_INPUT", f"payload too large: {len(payload_bytes)} > {self.limits.max_payload_bytes} bytes")

        # Validate available_at
        if available_at is not None:
            if not isinstance(available_at, (int, float)) or not (float("-inf") < available_at < float("inf")):
                raise SpoolError("INVALID_INPUT", "available_at must be a finite number")

        lock_fd = self._acquire_lock(exclusive=True)
        try:
            state = self._read_state(lock_fd)
            if state is None:
                raise SpoolError("NOT_INITIALIZED", "Spool not initialized")

            if self.failpoint is not None:
                self.failpoint("after_lock")

            # Check idempotency
            if message_id in state["messages"]:
                existing = state["messages"][message_id]
                existing_payload_canonical = json.dumps(existing["payload"], sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
                existing_available_at = existing["available_at"]
                if existing_payload_canonical == payload_canonical:
                    if (available_at is None) or (abs(existing_available_at - available_at) < 1e-9):
                        return self._message_public(existing)
                raise SpoolError("IDEMPOTENCY_CONFLICT", "message_id already used with different payload or available_at")

            # Check capacity
            if len(state["messages"]) >= self.limits.max_messages:
                raise SpoolError("CAPACITY_EXCEEDED", f"Max messages reached: {self.limits.max_messages}")

            # Use provided available_at or current clock
            if available_at is None:
                available_at = self.clock()

            # Assign sequence and create message
            sequence = state["next_sequence"]
            state["next_sequence"] += 1

            message = {
                "message_id": message_id,
                "payload": json.loads(payload_canonical),  # Store detached copy
                "status": "pending",
                "available_at": available_at,
                "sequence": sequence,
                "attempts": 0,
                "last_error": None,
            }
            state["messages"][message_id] = message

            self._write_state(state, lock_fd)
            return self._message_public(message)
        except SpoolError:
            raise
        except Exception as e:
            raise SpoolError("INTERNAL_ERROR", f"Failed to enqueue: {e}") from e
        finally:
            self._release_lock(lock_fd)

    def claim(self, worker_id: str) -> dict | None:
        if not isinstance(worker_id, str) or not worker_id.strip():
            raise SpoolError("INVALID_INPUT", "worker_id must be a non-empty non-whitespace string")

        lock_fd = self._acquire_lock(exclusive=True)
        try:
            state = self._read_state(lock_fd)
            if state is None:
                raise SpoolError("NOT_INITIALIZED", "Spool not initialized")

            if self.failpoint is not None:
                self.failpoint("after_lock")

            now = self.clock()

            # Find available messages
            candidates = []
            for msg in state["messages"].values():
                if msg["status"] == "pending" and msg["available_at"] <= now:
                    candidates.append(msg)

            if not candidates:
                return None

            # Sort and pick the first one
            candidates.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            msg = candidates[0]

            # Update message
            lease_token = secrets.token_urlsafe(32)
            expires_at = now + self.limits.lease_seconds

            msg["status"] = "leased"
            msg["attempts"] += 1
            msg["lease_token"] = lease_token
            msg["worker_id"] = worker_id
            msg["expires_at"] = expires_at

            self._write_state(state, lock_fd)
            return self._message_public(msg, include_lease_token=True)
        except SpoolError:
            raise
        except Exception as e:
            raise SpoolError("INTERNAL_ERROR", f"Failed to claim: {e}") from e
        finally:
            self._release_lock(lock_fd)

    def _constant_time_compare(self, a: str, b: str) -> bool:
        if len(a) != len(b):
            return False
        result = 0
        for x, y in zip(a, b):
            result |= ord(x) ^ ord(y)
        return result == 0

    def ack(self, message_id: str, lease_token: str) -> dict:
        if not isinstance(message_id, str) or not message_id.strip():
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty non-whitespace string")
        if not isinstance(lease_token, str) or not lease_token.strip():
            raise SpoolError("INVALID_INPUT", "lease_token must be a non-empty non-whitespace string")

        lock_fd = self._acquire_lock(exclusive=True)
        try:
            state = self._read_state(lock_fd)
            if state is None:
                raise SpoolError("NOT_INITIALIZED", "Spool not initialized")

            if self.failpoint is not None:
                self.failpoint("after_lock")

            if message_id not in state["messages"]:
                raise SpoolError("NOT_FOUND", f"Message not found: {message_id}")

            msg = state["messages"][message_id]

            if msg["status"] != "leased":
                raise SpoolError("INVALID_STATE", f"Message is not leased: {msg['status']}")

            if not self._constant_time_compare(msg["lease_token"], lease_token):
                raise SpoolError("UNAUTHORIZED", "Invalid lease token")

            # Ack the message
            msg["status"] = "acked"
            for key in ("lease_token", "worker_id", "expires_at"):
                if key in msg:
                    del msg[key]

            self._write_state(state, lock_fd)
            return self._message_public(msg)
        except SpoolError:
            raise
        except Exception as e:
            raise SpoolError("INTERNAL_ERROR", f"Failed to ack: {e}") from e
        finally:
            self._release_lock(lock_fd)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        if not isinstance(message_id, str) or not message_id.strip():
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty non-whitespace string")
        if not isinstance(lease_token, str) or not lease_token.strip():
            raise SpoolError("INVALID_INPUT", "lease_token must be a non-empty non-whitespace string")
        if not isinstance(error, str) or not error.strip():
            raise SpoolError("INVALID_INPUT", "error must be a non-empty non-whitespace string")

        lock_fd = self._acquire_lock(exclusive=True)
        try:
            state = self._read_state(lock_fd)
            if state is None:
                raise SpoolError("NOT_INITIALIZED", "Spool not initialized")

            if self.failpoint is not None:
                self.failpoint("after_lock")

            if message_id not in state["messages"]:
                raise SpoolError("NOT_FOUND", f"Message not found: {message_id}")

            msg = state["messages"][message_id]

            if msg["status"] != "leased":
                raise SpoolError("INVALID_STATE", f"Message is not leased: {msg['status']}")

            if not self._constant_time_compare(msg["lease_token"], lease_token):
                raise SpoolError("UNAUTHORIZED", "Invalid lease token")

            # Mark as failed
            for key in ("lease_token", "worker_id", "expires_at"):
                if key in msg:
                    del msg[key]

            msg["last_error"] = error
            if msg["attempts"] >= self.limits.max_attempts:
                msg["status"] = "dead"
            else:
                msg["status"] = "pending"
                msg["available_at"] = self.clock() + self.limits.retry_delay

            self._write_state(state, lock_fd)
            return self._message_public(msg)
        except SpoolError:
            raise
        except Exception as e:
            raise SpoolError("INTERNAL_ERROR", f"Failed to fail: {e}") from e
        finally:
            self._release_lock(lock_fd)

    def recover(self) -> dict:
        lock_fd = self._acquire_lock(exclusive=True)
        try:
            state = self._read_state(lock_fd)
            if state is None:
                raise SpoolError("NOT_INITIALIZED", "Spool not initialized")

            if self.failpoint is not None:
                self.failpoint("after_lock")

            now = self.clock()
            recovered_count = 0

            for msg in state["messages"].values():
                if msg["status"] == "leased" and now >= msg["expires_at"]:
                    recovered_count += 1
                    # Recover
                    for key in ("lease_token", "worker_id", "expires_at"):
                        if key in msg:
                            del msg[key]
                    if msg["attempts"] >= self.limits.max_attempts:
                        msg["status"] = "dead"
                    else:
                        msg["status"] = "pending"
                        msg["available_at"] = now

            self._write_state(state, lock_fd)
            return {"recovered": recovered_count}
        except SpoolError:
            raise
        except Exception as e:
            raise SpoolError("INTERNAL_ERROR", f"Failed to recover: {e}") from e
        finally:
            self._release_lock(lock_fd)

    def get(self, message_id: str) -> dict:
        if not isinstance(message_id, str) or not message_id.strip():
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty non-whitespace string")

        lock_fd = self._acquire_lock(exclusive=False)
        try:
            state = self._read_state(lock_fd)
            if state is None:
                raise SpoolError("NOT_INITIALIZED", "Spool not initialized")

            if message_id not in state["messages"]:
                raise SpoolError("NOT_FOUND", f"Message not found: {message_id}")

            return self._message_public(state["messages"][message_id])
        except SpoolError:
            raise
        except Exception as e:
            raise SpoolError("INTERNAL_ERROR", f"Failed to get: {e}") from e
        finally:
            self._release_lock(lock_fd)

    def list_messages(self, status=None) -> list[dict]:
        if status is not None:
            if not isinstance(status, str):
                raise SpoolError("INVALID_INPUT", "status must be a string if provided")
            valid_statuses = {"pending", "leased", "acked", "dead"}
            if status not in valid_statuses:
                raise SpoolError("INVALID_INPUT", f"Invalid status: {status}")

        lock_fd = self._acquire_lock(exclusive=False)
        try:
            state = self._read_state(lock_fd)
            if state is None:
                raise SpoolError("NOT_INITIALIZED", "Spool not initialized")

            messages = list(state["messages"].values())
            if status is not None:
                messages = [m for m in messages if m["status"] == status]

            # Sort by (available_at, sequence, message_id)
            messages.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            return [self._message_public(m) for m in messages]
        except SpoolError:
            raise
        except Exception as e:
