"""Delivery spool JSON CLI entry point."""

from __future__ import annotations

import argparse
import json
import sys
import time

from . import Limits, Spool, SpoolError


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", required=True, help="Path to spool root directory")
    parser.add_argument("command", choices=["init", "enqueue", "claim", "ack", "fail", "recover", "show", "list"], help="Command to execute")
    args = parser.parse_args()

    # Read input
    input_obj = {}
    if args.command not in ("init", "recover", "list"):
        try:
            line = sys.stdin.readline()
            if line.strip():
                input_obj = json.loads(line)
        except json.JSONDecodeError:
            print_error("INVALID_INPUT", "Invalid JSON input")
            sys.exit(2)
    else:
        # For init, recover, list, read optional input
        try:
            line = sys.stdin.readline()
            if line.strip():
                input_obj = json.loads(line)
                if not isinstance(input_obj, dict):
                    input_obj = {}
        except:
            input_obj = {}

    if not isinstance(input_obj, dict):
        print_error("INVALID_INPUT", "Input must be a JSON object")
        sys.exit(2)

    # Create spool
    try:
        spool = Spool(
            args.root,
            clock=time.time,
            limits=Limits(),
            lock_timeout=10.0,
            failpoint=None
        )
    except SpoolError as e:
        print_error(e.code, e.message, e.details)
        sys.exit(2)
    except Exception as e:
        print_error("INTERNAL_ERROR", str(e))
        sys.exit(3)

    # Execute command
    try:
        if args.command == "init":
            extra_keys = set(input_obj.keys())
            if extra_keys:
                raise SpoolError("INVALID_INPUT", f"Unknown keys: {sorted(extra_keys)}")
            result = spool.initialize()
        elif args.command == "enqueue":
            message_id = input_obj.get("message_id")
            payload = input_obj.get("payload")
            available_at = input_obj.get("available_at")
            extra_keys = set(input_obj.keys()) - {"message_id", "payload", "available_at"}
            if extra_keys:
                raise SpoolError("INVALID_INPUT", f"Unknown keys: {sorted(extra_keys)}")
            result = spool.enqueue(message_id, payload, available_at)
        elif args.command == "claim":
            worker_id = input_obj.get("worker_id")
            extra_keys = set(input_obj.keys()) - {"worker_id"}
            if extra_keys:
